import React from 'react'

const Home = () => {
  return (
    <div>
      <h1>Welcome to my Auth App</h1>
      <p>This is a full stack web application built with the MERN 
        (MongoDb,Express,React,Node.js) stack. it includes authentication features that allow users to 
        Sifn Up login and log out and provides access to protected routes only for auth
      </p>
    </div>
  )
}

export default Home
